/* Types (subset of data/plan.json, generated by analysis/model.py) and the small parsers the Plan tiles share. */

export interface Scenario {
  unique_verified_visitors: number;
  rounded: number;
  cost_per_visitor_inr: number;
  registrations: number;
  registrant_show: number;
  walkins?: number;
  engine?: { total: number };
}
export interface Step {
  key: string;
  label: string;
  delta: number;
  rounded?: number;
}
export interface Idea {
  rank: number;
  key: string;
  name: string;
  concept: string;
  budget_inr: number;
  owner: string;
  dates: string;
  test_design: string;
  kpis: string[];
  leading_indicator: string;
  thresholds: { scale: string; change: string; stop: string };
  critical_variable: string;
  biggest_risk: string;
  dashboard_ai: string;
  incremental_visitors_base: number;
  incremental_visitors_sponsor_band: number | null;
  incremental_visitors_stretch: number;
  person_weeks: number;
  ice: { I: number; C: number; E: number; I_basis?: string; C_basis?: string; E_basis?: string };
}
export interface Plan {
  meta: { fest: string; north_star: string };
  base: Scenario;
  stretch: Scenario;
  floor: Scenario & { definition?: unknown };
  sponsor_band: { delta_visitors: number; base_plus_band: number };
  waterfall: { base: unknown };
  growth_split_base: { growth: number; from_more_registrations: number; from_better_show_up: number; of_which_engine: number; of_which_mix_shift: number };
  funnel: { base: { stage: string; count: number; rate?: number; basis?: string }[]; stretch: { stage: string; count: number; rate?: number }[] };
  sensitivities: { base: { sensitivity: string; delta_visitors: number; basis: string }[] };
  pacing?: { base?: { weeks: string[]; weekly: number[]; cumulative: number[] } };
  budget: { lines: { key: string; idea: string | null; line: string; inr: number }[]; total: number };
  capacity: { base: Record<string, number>; stretch: Record<string, number>; permit_ask: string | Record<string, number>; fallback_venue?: string };
  ideas: Idea[];
  timeline: { phase: string; dates: string; items: string[] }[];
  checks: { check: string; pass: boolean; detail: string }[];
  inputs: Record<string, { value: unknown; flag: string; basis: string; source?: string } | unknown>;
}
export interface Initiative {
  id: string;
  rank: number;
  name: string;
  status: string;
  owner_name: string | null;
  task_count: number;
  tasks_done: number;
  evidence: { campaigns: string[]; spend: number; registrations: number; visitors: number | null; costPerVisitor: number | null; showRate: number | null } | null;
}

export const STATUS = ['planned', 'testing', 'scaling', 'changed', 'stopped', 'done'] as const;
export const STATUS_LABEL: Record<string, string> = { planned: 'Planned', testing: 'Testing', scaling: 'Scaling', changed: 'Changed', stopped: 'Stopped', done: 'Done' };

/** Engine references ("[cal HYD-20]", "[SHOW-02]") and Rs amounts, tidied for display. */
export const clean = (s: string) =>
  s
    .replace(/\s*\[[^\]]+\]/g, '')
    .replace(/Rs\s?/g, '₹')
    .replace(/ -> /g, ' to ')
    .trim();

const STEP_LABEL: Record<string, string> = {
  cut_paid: 'Paid cut',
  cut_creators: 'Creators cut',
  organic: 'Organic',
  community: 'Community',
  grid: 'College grid',
  bus: 'Shared bus',
  referrals: 'Squad Pass',
  ambassadors: 'Ambassadors',
  friend: 'Friend link',
  paid_gain: 'CTWA gain',
  compete: 'Compete',
  reserve: 'Reserve',
  engine: 'Show-up engine',
  walkins: 'Walk-ins',
};

type RawStep = { key?: string; label?: string; step?: string; delta?: number; exact?: number; integer?: number };
/** Waterfall steps; those that round to zero add noise, not information. */
export function stepsOf(w: unknown): Step[] {
  const arr = (Array.isArray(w) ? w : ((w as { steps?: RawStep[] })?.steps ?? [])) as RawStep[];
  return arr
    .map((s, i) => ({ key: s.key ?? String(i), label: s.label ?? s.step ?? '', delta: s.delta ?? s.exact ?? 0, rounded: s.integer }))
    .filter((s) => Math.abs(s.rounded ?? s.delta) >= 1);
}
export const stepLabel = (s: Step) => STEP_LABEL[s.key] ?? s.label.split(/[ (]/).slice(0, 2).join(' ');

/* ------------------------------------------------------------------ timeline */

const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const yearOf = (m: number, y?: string) => (y ? Number(y) : m >= 9 ? 2026 : 2027); // the plan runs Nov 2026 to Mar 2027
const iso = (y: number, m: number, d: number) => `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

/** "Thu 26 Nov - Fri 18 Dec 2026", "Mon 1 - Sun 7 Feb" → ISO start and end. */
export function phaseRange(dates: string): [string, string] | null {
  const parts = dates.split(/\s+-\s+/);
  if (parts.length !== 2) return null;
  const rx = /(\d{1,2})(?:\s+([A-Z][a-z]{2}))?(?:\s+(\d{4}))?\s*$/;
  const a = rx.exec(parts[0]);
  const b = rx.exec(parts[1]);
  if (!a || !b || !b[2]) return null;
  const mB = MON.indexOf(b[2]);
  const mA = a[2] ? MON.indexOf(a[2]) : mB;
  if (mA < 0 || mB < 0) return null;
  return [iso(yearOf(mA, a[3]), mA, Number(a[1])), iso(yearOf(mB, b[3]), mB, Number(b[1]))];
}

export interface Gate {
  key: string;
  label: string;
  short: string;
  date: string;
  text: string;
}

/** Dated gates ("Sun 17 Jan: GATE 0. Pass: ...") and the venue lock, in date order. */
export function gatesOf(timeline: Plan['timeline']): Gate[] {
  const out: Gate[] = [];
  for (const t of timeline)
    for (const item of t.items) {
      const dm = /^(?:[A-Z][a-z]{2}\s+)?(\d{1,2})\s+([A-Z][a-z]{2})\b/.exec(item);
      if (!dm || MON.indexOf(dm[2]) < 0) continue;
      const m = MON.indexOf(dm[2]);
      const date = iso(yearOf(m), m, Number(dm[1]));
      const g = /GATE (\d)[.:]\s*(.*)$/.exec(item);
      if (g) {
        const text = clean(g[2]);
        out.push({ key: `g${g[1]}`, label: `Gate ${g[1]}`, short: g[1], date, text: text.charAt(0).toUpperCase() + text.slice(1) });
        continue;
      }
      const lock = /LOCK\.\s*(.*)$/.exec(item);
      if (lock) out.push({ key: 'lock', label: 'Venue lock', short: 'V', date, text: clean(lock[1]).split('. ')[0] + '.' });
    }
  return out.sort((a, b) => a.date.localeCompare(b.date));
}

/** Short name of a bet: the live initiative's name, else the plan's name up to the colon. */
export const betName = (idea: Idea, live?: Initiative) => live?.name ?? idea.name.split(':')[0].replace(/^'|'$/g, '');
